import {json,requireAdmin} from '../../_lib.js';
import {ensureDatabase} from '../../_schema.js';
import {decryptChannelValue} from '../../_channel_crypto.js';
import {ensureV12Schema} from '../../_v12_schema.js';
import {fetchFacebookProfile} from '../../_facebook_profile.js';
const headers={'cache-control':'private, no-store'},clean=(v,n=500)=>String(v||'').replace(/[\u0000-\u001f\u007f]/g,' ').trim().slice(0,n),validImage=v=>/^https:\/\//i.test(v||'')?clean(v,500):'';
async function authorize(ctx){await ensureDatabase(ctx.env);await ensureV12Schema(ctx.env);const a=await requireAdmin(ctx);return a.error?{error:a.error}:a}
async function save(env,row,name,picture){const profile=validImage(picture),display=clean(name,120),nameChanged=Boolean(display&&display!==row.display_name),pictureChanged=Boolean(profile&&profile!==row.profile_url);if(!nameChanged&&!pictureChanged)return {name:false,picture:false};await env.DB.prepare("UPDATE veasy_conversations SET display_name=CASE WHEN ?!='' THEN ? ELSE display_name END,profile_url=CASE WHEN ?!='' THEN ? ELSE profile_url END WHERE shop_id=? AND id=?").bind(nameChanged?display:'',display,pictureChanged?profile:'',profile,row.shop_id,row.id).run();return {name:nameChanged,picture:pictureChanged}}
async function line(env,row){const credential=await env.DB.prepare("SELECT token_ciphertext FROM veasy_channel_credentials WHERE shop_id=? AND provider='line' AND verified_at IS NOT NULL").bind(row.shop_id).first();if(!credential?.token_ciphertext)return {reason:'not_ready'};const [token,target]=await Promise.all([decryptChannelValue(env,credential.token_ciphertext),decryptChannelValue(env,row.target_ciphertext)]),response=await fetch(`https://api.line.me/v2/bot/profile/${encodeURIComponent(target)}`,{headers:{authorization:`Bearer ${token}`}});if(!response.ok)return {reason:`line_http_${response.status}`};const data=await response.json().catch(()=>({})),saved=await save(env,row,data.displayName,data.pictureUrl);return {...saved,reason:saved.picture?'picture_ready':data.pictureUrl?'unchanged':'picture_missing'}}
async function facebook(env,row,token){const target=await decryptChannelValue(env,row.target_ciphertext),profile=await fetchFacebookProfile(target,token),saved=await save(env,row,profile.name,profile.picture);return {...saved,reason:profile.reason,http:profile.status,picture_http:profile.pictureStatus,error_code:profile.errorCode,error_subcode:profile.errorSubcode}}
const safeReason=result=>{const parts=[result.reason];if(result.http)parts.push(`http_${result.http}`);if(result.picture_http)parts.push(`picture_http_${result.picture_http}`);if(result.error_code)parts.push(`meta_${result.error_code}`);if(result.error_subcode)parts.push(`sub_${result.error_subcode}`);return parts.join(':')};
export async function onRequestPost(ctx){
  const auth=await authorize(ctx);if(auth.error)return auth.error;
  const rows=(await ctx.env.DB.prepare(`SELECT c.id,c.shop_id,c.platform,c.display_name,c.profile_url,k.target_ciphertext FROM veasy_conversations c JOIN veasy_conversation_controls k ON k.shop_id=c.shop_id AND k.conversation_id=c.id WHERE c.status='active' AND c.platform IN ('line','facebook') AND c.profile_url='' ORDER BY c.updated_at DESC LIMIT 40`).all()).results||[];
  const credential=rows.some(row=>row.platform==='facebook')?await ctx.env.DB.prepare("SELECT token_ciphertext FROM v12_channel_credentials WHERE provider='facebook' AND verified_at IS NOT NULL").first():null,facebookToken=credential?.token_ciphertext?await decryptChannelValue(ctx.env,credential.token_ciphertext):'';
  let pictureUpdated=0,nameUpdated=0,failed=0,notReady=0;const reasons={};
  for(let index=0;index<rows.length;index+=5){const batch=rows.slice(index,index+5),results=await Promise.all(batch.map(async row=>{try{if(row.platform==='facebook'&&!facebookToken)return {reason:'not_ready'};return row.platform==='line'?await line(ctx.env,row):await facebook(ctx.env,row,facebookToken)}catch{return {reason:'unexpected'}}}));for(const result of results){if(result.picture)pictureUpdated++;if(result.name)nameUpdated++;if(result.reason==='not_ready')notReady++;if(!result.picture&&result.reason!=='unchanged'&&result.reason!=='not_ready')failed++;const key=safeReason(result);reasons[key]=(reasons[key]||0)+1}}
  return json({ok:true,checked:rows.length,picture_updated:pictureUpdated,name_updated:nameUpdated,failed,not_ready:notReady,reasons,limitation:'ดึงไม่ได้เฉพาะลูกค้าและข้อความก่อนติดตั้ง Webhook ที่ไม่มี Conversation ID'},200,headers);
}
