import {json,requireAdmin} from '../../../../_lib.js';import {ensureDatabase} from '../../../../_schema.js';import {queueMetaReply,processMetaOutbox} from '../../../../_meta_sender.js';
export async function onRequestPost(ctx){await ensureDatabase(ctx.env);const auth=await requireAdmin(ctx);if(auth.error)return auth.error;const body=await ctx.request.json().catch(()=>({})),queued=await queueMetaReply(ctx.env,{conversationId:String(ctx.params.id),content:body.content,createdBy:auth.user.id,idempotencyKey:ctx.request.headers.get('idempotency-key')});if(queued.error)return json({error:queued.error,code:queued.code},queued.status);if(queued.duplicate)return json(queued);try{const run=await processMetaOutbox(ctx.env,{limit:1}),item=run.results.find(x=>x.id===queued.id);return json({ok:true,queued,item:item||null})}catch(error){return json({ok:true,queued,delivery:'queued_for_retry',code:String(error?.message||'META_SEND_DEFERRED')},202)}}
