import {json} from '../../_lib.js';import {ensureDatabase} from '../../_schema.js';import {ensureVision7Schema} from '../../_vision7_schema.js';
export async function onRequestGet(ctx){await ensureDatabase(ctx.env);await ensureVision7Schema(ctx.env);const rows=await ctx.env.DB.prepare(`SELECT p.id,p.code,p.platform_type,p.current_version,p.requires_online,p.max_devices,p.trial_hours,x.title,x.short_description,x.cover_url,(SELECT json_group_array(json_object('id',q.id,'code',q.plan_code,'name',q.name,'price',q.price,'duration_days',q.duration_days)) FROM vision7_plans q WHERE q.program_id=p.id AND q.active=1) plans FROM vision7_programs p LEFT JOIN products x ON x.id=p.product_id WHERE p.active=1 ORDER BY p.updated_at DESC`).all();return json({items:rows.results||[]});}
