import {ensurePartnerSchema} from './_partner_api.js';
const forbidden=/(?:^|_)(?:password|passcode|access_token|refresh_token|api_key|client_secret|authorization|card_number|pan|cvv|cvc|expiry|bank_account|account_number|routing_number|swift|iban)(?:$|_)/i;
export async function ensurePartnerSyncSchema(env){await ensurePartnerSchema(env);await env.DB.exec(`CREATE TABLE IF NOT EXISTS partner_customers (id TEXT PRIMARY KEY,website_id TEXT NOT NULL,external_customer_id TEXT NOT NULL,profile_ciphertext TEXT NOT NULL,email_hash TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive','deleted')),external_created_at TEXT,last_synced_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(website_id,external_customer_id),FOREIGN KEY(website_id) REFERENCES partner_websites(id) ON DELETE CASCADE);CREATE INDEX IF NOT EXISTS idx_partner_customers_website ON partner_customers(website_id,updated_at DESC);CREATE TABLE IF NOT EXISTS partner_orders (id TEXT PRIMARY KEY,website_id TEXT NOT NULL,external_order_id TEXT NOT NULL,external_customer_id TEXT,status TEXT NOT NULL CHECK(status IN ('pending','paid','cancelled','partially_refunded','refunded')),payment_status TEXT NOT NULL CHECK(payment_status IN ('unpaid','pending','paid','failed','partially_refunded','refunded')),currency TEXT NOT NULL DEFAULT 'THB',subtotal INTEGER NOT NULL CHECK(subtotal>=0),discount INTEGER NOT NULL DEFAULT 0 CHECK(discount>=0),total INTEGER NOT NULL CHECK(total>=0),refunded_amount INTEGER NOT NULL DEFAULT 0 CHECK(refunded_amount>=0),external_created_at TEXT,external_updated_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(website_id,external_order_id),FOREIGN KEY(website_id) REFERENCES partner_websites(id) ON DELETE CASCADE);CREATE INDEX IF NOT EXISTS idx_partner_orders_website ON partner_orders(website_id,updated_at DESC);CREATE TABLE IF NOT EXISTS partner_order_items (order_id TEXT NOT NULL,line_index INTEGER NOT NULL,external_product_id TEXT NOT NULL,sku TEXT NOT NULL DEFAULT '',title TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),unit_price INTEGER NOT NULL CHECK(unit_price>=0),line_total INTEGER NOT NULL CHECK(line_total>=0),PRIMARY KEY(order_id,line_index),FOREIGN KEY(order_id) REFERENCES partner_orders(id) ON DELETE CASCADE);CREATE TABLE IF NOT EXISTS partner_refunds (id TEXT PRIMARY KEY,order_id TEXT NOT NULL,external_refund_id TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),status TEXT NOT NULL CHECK(status IN ('pending','completed','failed')),reason TEXT NOT NULL DEFAULT '',external_created_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(order_id,external_refund_id),FOREIGN KEY(order_id) REFERENCES partner_orders(id) ON DELETE CASCADE);CREATE TABLE IF NOT EXISTS partner_idempotency (website_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,resource_type TEXT NOT NULL,external_id TEXT NOT NULL,response_status INTEGER NOT NULL,response_body TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(website_id,idempotency_key),FOREIGN KEY(website_id) REFERENCES partner_websites(id) ON DELETE CASCADE);CREATE INDEX IF NOT EXISTS idx_partner_idempotency_created ON partner_idempotency(created_at);`)}
export async function ensurePartnerSyncReady(env){if(await ensurePartnerSchema(env))return true;await ensurePartnerSyncSchema(env);return false}
export function forbiddenDataPath(value,path='payload'){if(Array.isArray(value)){for(let index=0;index<value.length;index++){const found=forbiddenDataPath(value[index],`${path}[${index}]`);if(found)return found}return ''}if(value&&typeof value==='object'){for(const [key,child] of Object.entries(value)){if(forbidden.test(key))return `${path}.${key}`;const found=forbiddenDataPath(child,`${path}.${key}`);if(found)return found}}return ''}
const canonical=value=>Array.isArray(value)?value.map(canonical):value&&typeof value==='object'?Object.fromEntries(Object.keys(value).sort().map(key=>[key,canonical(value[key])])):value;
export const payloadHash=value=>sha256(JSON.stringify(canonical(value)));
export const cleanId=(value,max=120)=>{const text=String(value||'').trim();return /^[A-Za-z0-9][A-Za-z0-9._:-]*$/.test(text)&&text.length<=max?text:''};
export const cleanText=(value,max=300)=>String(value||'').trim().slice(0,max);
export const cleanEmail=value=>{const email=cleanText(value,254).toLowerCase();return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)?email:''};
export const cleanPhone=value=>{const phone=cleanText(value,30);return /^[+0-9 ()-]{6,30}$/.test(phone)?phone:''};
export const cents=value=>Number.isInteger(value)&&value>=0&&value<=100000000?value:null;
export const isoTime=value=>{if(!value)return null;const date=new Date(value);return Number.isNaN(date.valueOf())?'':date.toISOString()};
export const internalPartnerId=async(prefix,websiteId,externalId)=>`${prefix}_${(await sha256(`${websiteId}:${externalId}`)).slice(0,32)}`;
export function idempotencyKey(request){const key=String(request.headers.get('idempotency-key')||'').trim();return /^[A-Za-z0-9][A-Za-z0-9._:-]{7,99}$/.test(key)?key:''}
export async function idempotencyCheck(env,websiteId,key,hash){const row=await env.DB.prepare('SELECT request_hash,response_status,response_body FROM partner_idempotency WHERE website_id=? AND idempotency_key=?').bind(websiteId,key).first();if(!row)return null;if(row.request_hash!==hash)return {error:json({error:'IDEMPOTENCY_KEY_REUSED_WITH_DIFFERENT_PAYLOAD'},409,{'cache-control':'no-store'})};let body={};try{body=JSON.parse(row.response_body)}catch{}return {response:json({...body,idempotent_replay:true},row.response_status,{'cache-control':'no-store'})}}
export const idempotencyWrite=(env,{websiteId,key,hash,type,externalId,status,body})=>env.DB.prepare('INSERT OR IGNORE INTO partner_idempotency(website_id,idempotency_key,request_hash,resource_type,external_id,response_status,response_body) VALUES(?,?,?,?,?,?,?)').bind(websiteId,key,hash,type,externalId,status,JSON.stringify(body));
