const clean=(value,max=500)=>String(value||'').replace(/[\u0000-\u001f\u007f]/g,' ').trim().replace(/\s+/g,' ').slice(0,max);
const imageUrl=value=>/^https:\/\//i.test(value||'')?clean(value,1000):'';
async function graphJson(url,token){const response=await fetch(url,{headers:{authorization:`Bearer ${token}`}}),data=await response.json().catch(()=>({}));return {ok:response.ok,status:response.status,data,errorCode:Number(data?.error?.code||0),errorSubcode:Number(data?.error?.error_subcode||0)}}
export async function fetchFacebookProfile(psid,token,fallbackName=''){const id=encodeURIComponent(psid),profile=await graphJson(`https://graph.facebook.com/${id}?fields=first_name,last_name,name,profile_pic`,token),data=profile.data||{};let picture=imageUrl(data.profile_pic),pictureResult=null;if(!picture){pictureResult=await graphJson(`https://graph.facebook.com/${id}/picture?redirect=false&type=large`,token);if(pictureResult.ok&&!pictureResult.data?.data?.is_silhouette)picture=imageUrl(pictureResult.data?.data?.url)}const composed=clean([data.first_name,data.last_name].filter(Boolean).join(' '),120),reason=picture?'picture_ready':!profile.ok?'profile_denied':pictureResult&&!pictureResult.ok?'picture_denied':pictureResult?.data?.data?.is_silhouette?'silhouette':'picture_missing';return {ok:profile.ok,name:clean(data.name||composed||fallbackName,120),picture,status:profile.status,pictureStatus:pictureResult?.status||0,errorCode:profile.errorCode||pictureResult?.errorCode||0,errorSubcode:profile.errorSubcode||pictureResult?.errorSubcode||0,reason}}
