import {json} from '../../../_lib.js';import {ensureDatabase} from '../../../_schema.js';import {ensureSalesPageSchema} from '../../../_sales_pages.js';import {ensureSalesPageVariantSchema} from '../../../_sales_page_variants.js';export async function onRequestGet(ctx){await ensureDatabase(ctx.env);await ensureSalesPageSchema(ctx.env);await ensureSalesPageVariantSchema(ctx.env);const page=await ctx.env.DB.prepare("SELECT id FROM sales_pages WHERE id=? AND page_type='ad_shortcut' AND status='published' AND robots_index=0").bind(ctx.params.id).first();if(!page)return json({error:'ไม่พบหน้าขาย'},404,{'cache-control':'no-store'});const rows=(await ctx.env.DB.prepare('SELECT variant_key,name,weight,content_json FROM sales_page_variants WHERE page_id=? AND active=1 AND weight>0 ORDER BY variant_key').bind(page.id).all()).results||[];return json({variants:rows.map(row=>({...row,content:JSON.parse(row.content_json||'{}')}))},200,{'cache-control':'public, max-age=60'})}
