import {json,requireBoss} from '../../../_lib.js';import {ensureDatabase} from '../../../_schema.js';import {ensureVision14Schema} from '../../../_vision14.js';const headers={'cache-control':'private, no-store'},parse=value=>{try{return JSON.parse(value||'[]')}catch{return[]}},hash=async value=>{const bytes=new TextEncoder().encode(value),digest=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(digest)].map(byte=>byte.toString(16).padStart(2,'0')).join('')};
async function auth(ctx){await ensureDatabase(ctx.env);await ensureVision14Schema(ctx.env);return requireBoss(ctx)}
async function data(env,id){const queue=await env.DB.prepare(`SELECT q.*,m.title,m.item_count,m.duplicate_count,m.internal_only FROM vision13_intake_queue q JOIN vision14_mixes m ON m.id=q.mix_id WHERE q.id=?`).bind(id).first();if(!queue)return null;const sources=(await env.DB.prepare(`SELECT s.source_id,v.title,s.rights_status,s.sale_eligible,d.id teaching_document_id FROM vision14_mix_sources s JOIN vision14_sources v ON v.id=s.source_id LEFT JOIN vision14_teaching_documents d ON d.source_id=s.source_id WHERE s.mix_id=? ORDER BY v.title`).bind(queue.mix_id).all()).results||[],items=(await env.DB.prepare('SELECT id,canonical_text,fingerprint,citations FROM vision14_mix_items WHERE mix_id=? ORDER BY id').bind(queue.mix_id).all()).results||[],reviews=(await env.DB.prepare(`SELECT r.id,r.action,r.note,r.snapshot_hash,r.created_at,u.name reviewer_name FROM vision13_intake_reviews r LEFT JOIN users u ON u.id=r.reviewed_by WHERE r.queue_id=? ORDER BY r.id DESC`).bind(queue.id).all()).results||[],production=await env.DB.prepare('SELECT id,artifact_hash,file_size,item_count,created_at FROM vision13_ebook_productions WHERE queue_id=?').bind(queue.id).first();return{queue,sources,items:items.map(item=>({...item,citations:parse(item.citations)})),reviews,production}}
export async function onRequestGet(ctx){const a=await auth(ctx);if(a.error)return a.error;const result=await data(ctx.env,ctx.params.id);return result?json(result,200,headers):json({error:'ไม่พบงาน Intake'},404,headers)}
export async function onRequestPut(ctx){const a=await auth(ctx);if(a.error)return a.error;const body=await ctx.request.json().catch(()=>null),action=String(body?.action||''),note=String(body?.note||'').trim().slice(0,1000),result=await data(ctx.env,ctx.params.id);if(!result)return json({error:'ไม่พบงาน Intake'},404,headers);const current=result.queue.status,allowed={ready:['start_review'],reviewing:['approve','reject'],rejected:['start_review'],approved:[]};if(!(allowed[current]||[]).includes(action))return json({error:`เปลี่ยนสถานะจาก ${current} ด้วย ${action} ไม่ได้`},409,headers);if(action==='reject'&&!note)return json({error:'การตีกลับต้องระบุเหตุผล'},400,headers);let next=action==='start_review'?'reviewing':action==='approve'?'approved':'rejected',snapshot='';if(action==='approve'){if(result.queue.internal_only||result.sources.some(source=>!Number(source.sale_eligible)||!source.teaching_document_id))return json({error:'สิทธิ์หรือ PDF สอนไม่ครบ ห้ามอนุมัติผลิต E-book'},409,headers);if(!result.items.length||result.items.some(item=>item.fingerprint.length!==64||!item.citations.length))return json({error:'Fingerprint หรือ Citation ไม่ครบ'},409,headers);snapshot=await hash(result.items.map(item=>`${item.id}:${item.fingerprint}:${JSON.stringify(item.citations)}`).join('|'))}await ctx.env.DB.batch([ctx.env.DB.prepare('UPDATE vision13_intake_queue SET status=?,last_error=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(next,action==='reject'?note:'',result.queue.id),ctx.env.DB.prepare('INSERT INTO vision13_intake_reviews(queue_id,action,note,snapshot_hash,reviewed_by) VALUES(?,?,?,?,?)').bind(result.queue.id,action,note,snapshot,a.user.id),ctx.env.DB.prepare('UPDATE vision14_mixes SET status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(next==='approved'?'vision13_approved':next==='rejected'?'vision13_rejected':'vision13_reviewing',result.queue.mix_id)]);return json({ok:true,status:next,snapshot_hash:snapshot||null},200,headers)}
