import {json,requireAdmin} from '../../../../_lib.js';import {ensureDatabase} from '../../../../_schema.js';import {ensureSalesPageSchema,salesPageContent} from '../../../../_sales_pages.js';import {ensureSalesPageVariantSchema} from '../../../../_sales_page_variants.js';const headers={'cache-control':'private, no-store'};async function auth(ctx){await ensureDatabase(ctx.env);await ensureSalesPageSchema(ctx.env);await ensureSalesPageVariantSchema(ctx.env);return requireAdmin(ctx)}
export async function onRequestGet(ctx){const a=await auth(ctx);if(a.error)return a.error;const page=await ctx.env.DB.prepare("SELECT id,title,slug FROM sales_pages WHERE id=? AND page_type='ad_shortcut'").bind(ctx.params.id).first();if(!page)return json({error:'ไม่พบ Ad Shortcut'},404,headers);const variants=(await ctx.env.DB.prepare('SELECT variant_key,name,weight,content_json,active,updated_at FROM sales_page_variants WHERE page_id=? ORDER BY variant_key').bind(page.id).all()).results.map(item=>({...item,content:JSON.parse(item.content_json||'{}')}));const stats=(await ctx.env.DB.prepare(`SELECT CASE WHEN content LIKE ? THEN substr(content,length(?)+2) ELSE COALESCE(NULLIF(content,''),'A') END variant,event_type,COUNT(*) count FROM customer_events WHERE (path=? OR content LIKE ?) AND created_at>=datetime('now','-30 days') GROUP BY variant,event_type`).bind(`${page.slug}:%`,page.slug,`/s/${page.slug}`,`${page.slug}:%`).all()).results||[];return json({page,variants,stats},200,headers)}
export async function onRequestPut(ctx){const a=await auth(ctx);if(a.error)return a.error;const page=await ctx.env.DB.prepare("SELECT id FROM sales_pages WHERE id=? AND page_type='ad_shortcut'").bind(ctx.params.id).first();if(!page)return json({error:'ไม่พบ Ad Shortcut'},404,headers);const body=await ctx.request.json().catch(()=>null),variants=Array.isArray(body?.variants)?body.variants:[];if(variants.length!==2||!variants.some(v=>v.variant_key==='A')||!variants.some(v=>v.variant_key==='B'))return json({error:'ต้องมี Variant A และ B'},400,headers);const normalized=variants.map(v=>({key:String(v.variant_key),name:String(v.name||`Variant ${v.variant_key}`).trim().slice(0,80),weight:Number(v.weight),content:salesPageContent(v.content),active:v.active!==false}));if(normalized.some(v=>!Number.isInteger(v.weight)||v.weight<0||v.weight>100)||normalized.filter(v=>v.active).reduce((sum,v)=>sum+v.weight,0)!==100)return json({error:'น้ำหนัก Variant ที่เปิดใช้ต้องรวม 100'},400,headers);await ctx.env.DB.batch(normalized.map(v=>ctx.env.DB.prepare(`INSERT INTO sales_page_variants(page_id,variant_key,name,weight,content_json,active,updated_by) VALUES(?,?,?,?,?,?,?) ON CONFLICT(page_id,variant_key) DO UPDATE SET name=excluded.name,weight=excluded.weight,content_json=excluded.content_json,active=excluded.active,updated_by=excluded.updated_by,updated_at=CURRENT_TIMESTAMP`).bind(page.id,v.key,v.name,v.weight,JSON.stringify(v.content),v.active?1:0,a.user.id)));return json({ok:true},200,headers)}
