import {json} from '../../../../_lib.js';import {ensureDatabase} from '../../../../_schema.js';import {requireVision7User} from '../../../../_vision7_auth.js';import {channelEncryptionReady,decryptChannelValue,encryptChannelValue} from '../../../../_channel_crypto.js';import {createWebhook,ensureWebhookHubSchema,projectWebhook} from '../../../../_webhook_hub.js';import {veasyAiProviderStatus} from '../../../../_veasy_line_ai.js';
const ns={'cache-control':'private, no-store'};async function owned(ctx,user){return ctx.env.DB.prepare('SELECT id FROM veasy_shops WHERE id=? AND user_id=?').bind(ctx.params.shopId,user.id).first()}async function authorize(ctx){await ensureDatabase(ctx.env);await ensureWebhookHubSchema(ctx.env);const a=await requireVision7User(ctx);if(a.error)return a;if(!await owned(ctx,a.user))return {error:json({error:'ไม่พบร้านที่เป็นเจ้าของ'},404,ns)};return a}async function endpoint(ctx){return ctx.env.DB.prepare("SELECT * FROM veasy_webhook_endpoints WHERE shop_id=? AND provider='line' AND status!='revoked'").bind(ctx.params.shopId).first()}
export async function onRequestGet(ctx){const a=await authorize(ctx);if(a.error)return a.error;const [c,h]=await Promise.all([ctx.env.DB.prepare("SELECT external_account_id,verified_at,updated_at FROM veasy_channel_credentials WHERE shop_id=? AND provider='line'").bind(ctx.params.shopId).first(),endpoint(ctx)]),ready=channelEncryptionReady(ctx.env),saved=Boolean(c),lineReady=Boolean(c?.verified_at&&h?.status==='active'&&h?.adapter_state==='ready');if(lineReady)await ctx.env.DB.prepare("INSERT INTO veasy_channels(shop_id,platform,status,external_id) VALUES(?,'line','connected',?) ON CONFLICT(shop_id,platform) DO UPDATE SET status='connected',external_id=excluded.external_id,updated_at=CURRENT_TIMESTAMP").bind(ctx.params.shopId,String(c.external_account_id||'')).run();return json({configured:saved,credentials_saved:saved,credential_input_required:!saved,credential_display:saved?'••••••••':'',connected:lineReady,encryption_ready:ready,ai:veasyAiProviderStatus(ctx.env),setup_required:ready?null:{code:'CHANNEL_ENCRYPTION_NOT_CONFIGURED',secret_name:'VISIOND_CHANNEL_ENCRYPTION_KEY',minimum_length:32,action:'เพิ่ม Secret ใน Cloudflare แล้ว Redeploy โดยไม่ต้องออก LINE Token ใหม่'},external_account_id:c?.external_account_id||'',verified_at:c?.verified_at||null,webhook:h?projectWebhook(ctx.env,h):null},200,ns)}
export async function onRequestPut(ctx){const a=await authorize(ctx);if(a.error)return a.error;if(!channelEncryptionReady(ctx.env))return json({error:'ระบบเว็บยังตั้งค่าการเข้ารหัส LINE ไม่ครบ กรุณาให้ Boss เพิ่ม Secret VISIOND_CHANNEL_ENCRYPTION_KEY แล้ว Redeploy · ไม่ต้องออก LINE Token ใหม่ และข้อมูลที่กรอกในหน้านี้ยังใช้ลองใหม่ได้',code:'CHANNEL_ENCRYPTION_NOT_CONFIGURED',retryable:true},503,ns);const b=await ctx.request.json().catch(()=>({})),secret=String(b.channel_secret||'').trim(),token=String(b.access_token||'').trim(),account=String(b.channel_id||'').trim();if(secret.length<16||token.length<40)return json({error:'Channel Secret หรือ Channel Access Token ไม่ครบ กรุณาคัดลอกค่าเต็มจาก LINE Developers',code:'LINE_CREDENTIALS_INCOMPLETE'},400,ns);const [se,te]=await Promise.all([encryptChannelValue(ctx.env,secret),encryptChannelValue(ctx.env,token)]);let hook=await endpoint(ctx);try{if(!hook)hook=await createWebhook(ctx.env,{shopId:ctx.params.shopId,provider:'line',actorId:a.user.id});await ctx.env.DB.prepare(`INSERT INTO veasy_channel_credentials(shop_id,provider,external_account_id,secret_ciphertext,token_ciphertext) VALUES(?,'line',?,?,?) ON CONFLICT(shop_id,provider) DO UPDATE SET external_account_id=excluded.external_account_id,secret_ciphertext=excluded.secret_ciphertext,token_ciphertext=excluded.token_ciphertext,verified_at=NULL,updated_at=CURRENT_TIMESTAMP`).bind(ctx.params.shopId,account,se,te).run();await ctx.env.DB.prepare("UPDATE veasy_webhook_endpoints SET adapter_state='pending',status='draft',updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(hook.id).run();return json({ok:true,webhook_url:projectWebhook(ctx.env,hook).webhook_url,message:'บันทึกแบบเข้ารหัสแล้ว กรุณาทดสอบการเชื่อมต่อ'},200,ns)}catch(error){console.error('LINE_CONNECTION_SAVE_FAILED',{shopId:ctx.params.shopId,error:String(error)});return json({error:'บันทึก LINE ไม่สำเร็จ ข้อมูลที่กรอกยังอยู่ กรุณาลองใหม่',code:'LINE_CONNECTION_SAVE_FAILED',retryable:true},500,ns)}}
export async function onRequestPost(ctx){const a=await authorize(ctx);if(a.error)return a.error;if(!channelEncryptionReady(ctx.env))return json({error:'ระบบเว็บยังตั้ง VISIOND_CHANNEL_ENCRYPTION_KEY ไม่ครบ จึงยังทดสอบไม่ได้',code:'CHANNEL_ENCRYPTION_NOT_CONFIGURED'},503,ns);const row=await ctx.env.DB.prepare("SELECT token_ciphertext FROM veasy_channel_credentials WHERE shop_id=? AND provider='line'").bind(ctx.params.shopId).first(),hook=await endpoint(ctx);if(!row||!hook)return json({error:'กรุณาบันทึก Channel Secret และ Token ก่อน'},400,ns);try{const token=await decryptChannelValue(ctx.env,row.token_ciphertext),r=await fetch('https://api.line.me/v2/bot/info',{headers:{authorization:`Bearer ${token}`}}),profile=await r.json().catch(()=>({}));if(!r.ok)throw new Error(profile.message||`LINE HTTP ${r.status}`);await ctx.env.DB.batch([ctx.env.DB.prepare("UPDATE veasy_channel_credentials SET verified_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE shop_id=? AND provider='line'").bind(ctx.params.shopId),ctx.env.DB.prepare("UPDATE veasy_webhook_endpoints SET adapter_state='ready',status='active',updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(hook.id),ctx.env.DB.prepare("INSERT INTO veasy_channels(shop_id,platform,status,external_id) VALUES(?,'line','connected',?) ON CONFLICT(shop_id,platform) DO UPDATE SET status='connected',external_id=excluded.external_id,updated_at=CURRENT_TIMESTAMP").bind(ctx.params.shopId,String(profile.basicId||''))]);return json({ok:true,profile:{display_name:profile.displayName||'',basic_id:profile.basicId||''},webhook_url:projectWebhook(ctx.env,{...hook,status:'active',adapter_state:'ready'}).webhook_url},200,ns)}catch(error){await ctx.env.DB.batch([ctx.env.DB.prepare("UPDATE veasy_webhook_endpoints SET adapter_state='error',status='draft',updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(hook.id),ctx.env.DB.prepare("INSERT INTO veasy_channels(shop_id,platform,status) VALUES(?,'line','error') ON CONFLICT(shop_id,platform) DO UPDATE SET status='error',updated_at=CURRENT_TIMESTAMP").bind(ctx.params.shopId)]).catch(()=>{});return json({error:`ทดสอบ LINE ไม่ผ่าน: ${String(error.message||error)}`,code:'LINE_CONNECTION_TEST_FAILED'},400,ns)}}
