import {ensurePartnerWebhookSchema} from './_partner_webhook.js';
import {ensurePartnerSchema} from './_partner_api.js';
export async function ensurePartnerHealthSchema(env){if(await ensurePartnerSchema(env))return true;await ensurePartnerWebhookSchema(env);const columns=(await env.DB.prepare('PRAGMA table_info(partner_webhook_events)').all()).results||[];if(!columns.some(column=>column.name==='duration_ms'))await env.DB.exec('ALTER TABLE partner_webhook_events ADD COLUMN duration_ms INTEGER NOT NULL DEFAULT 0 CHECK(duration_ms>=0)');await env.DB.exec('CREATE INDEX IF NOT EXISTS idx_partner_webhook_health ON partner_webhook_events(website_id,received_at,status,duration_ms)');return false}
export function buildPartnerAlerts({signatureErrors=0,timestampErrors=0,retry=0,dead=0}){const alerts=[];if(Number(signatureErrors)>0)alerts.push({code:'SIGNATURE_FAILURE',level:'critical',message:`ลายเซ็นผิด ${Number(signatureErrors)} ครั้งใน 24 ชั่วโมง`});if(Number(timestampErrors)>0)alerts.push({code:'TIMESTAMP_EXPIRED',level:'warning',message:`Timestamp เกินกำหนด ${Number(timestampErrors)} ครั้งใน 24 ชั่วโมง`});if(Number(retry)>=3)alerts.push({code:'RETRY_ACCUMULATED',level:'warning',message:`Retry ค้างสะสม ${Number(retry)} Event`});if(Number(dead)>0)alerts.push({code:'DEAD_LETTER_PRESENT',level:'critical',message:`มี Dead Letter ${Number(dead)} Event`});return alerts}
