import { json, requireUser } from "../../_lib.js";
import { ensureDatabase } from "../../_schema.js";
import {COURSE_PLANS,coursePlan} from '../../_course_plans.js';
import {MIN_COURSE_PRICE_SATANG,coursePriceError} from '../../_course_rules.js';
const imageTypes = ["image/jpeg", "image/png", "image/webp"],
  ext = (name, type) =>
    String(name || "")
      .split(".")
      .pop()
      ?.toLowerCase() ||
    { "image/jpeg": "jpg", "image/png": "png", "image/webp": "webp" }[type] ||
    "bin",
  slugify = (v) =>
    String(v || "")
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9ก-๙]+/g, "-")
      .replace(/^-|-$/g, "")
      .slice(0, 70) || `course-${Date.now()}`;
async function putImage(env, file) {
  if (!(file instanceof File) || !file.size) return null;
  if (!imageTypes.includes(file.type) || file.size > 8 * 1024 * 1024)
    throw new Error("IMAGE_INVALID");
  const key = `user-course-cover-${crypto.randomUUID()}.${ext(file.name, file.type)}`;
  await env.FILES.put(key, await file.arrayBuffer(), {
    httpMetadata: { contentType: file.type },
  });
  return key;
}
export async function onRequestGet(ctx) {
  await ensureDatabase(ctx.env);
  const auth = await requireUser(ctx);
  if (auth.error) return auth.error;
  const credits = await ctx.env.DB.prepare(
    `SELECT cr.id credit_id,cr.active,cr.used_at,cr.granted_at,p.title license_title FROM course_right_credits cr JOIN products p ON p.id=cr.product_id WHERE cr.user_id=? ORDER BY cr.id DESC`,
  )
    .bind(auth.user.id)
    .all();
  const licenses = (credits.results || []).map((x) => ({
    ...x,
    entitlement_id: `credit-${x.credit_id}`,
    available: Boolean(x.active),
    credit: 1,
  }));
  const courses = await ctx.env.DB.prepare(
    `SELECT c.id,c.license_entitlement_id,c.course_plan,p.slug,p.title,p.short_description,p.description,p.price,p.cover_url,p.status,c.teacher_name,c.contact_info,c.platform_tags,c.learner_level,c.expected_episodes,c.review_status,c.review_note,c.submitted_at,c.edit_expires_at,p.updated_at,COALESCE((SELECT COUNT(*) FROM course_lessons l WHERE l.course_id=c.id AND TRIM(COALESCE(l.title,''))<>'' AND (l.video_key IS NOT NULL OR l.pdf_key IS NOT NULL OR EXISTS(SELECT 1 FROM course_lesson_files f WHERE f.lesson_id=l.id))),0) planned_lesson_count,COALESCE((SELECT COUNT(*) FROM course_lessons l WHERE l.course_id=c.id AND TRIM(COALESCE(l.title,''))<>'' AND (l.video_key IS NOT NULL OR l.pdf_key IS NOT NULL OR EXISTS(SELECT 1 FROM course_lesson_files f WHERE f.lesson_id=l.id))),0) lesson_count FROM courses c JOIN products p ON p.id=c.product_id WHERE (c.owner_user_id=? OR EXISTS(SELECT 1 FROM course_right_credits own_credit WHERE own_credit.used_course_id=c.id AND own_credit.user_id=?)) AND c.course_origin='seller_rights' AND p.deleted_at IS NULL ORDER BY c.id DESC`,
  )
    .bind(auth.user.id, auth.user.id)
    .all();
  const createOnly = new URL(ctx.request.url).searchParams.get("scope") === "create";
  if (createOnly) {
    const items = courses.results || [],
      assignedDrafts = items.filter((x) => x.license_entitlement_id !== null);
    return json(
      {
        licenses,
        courses: items,
        sales: [],
        sales_list_limited: false,
        slip_issues: [],
        totals: { amount: 0, orders: 0 },
        course_draft_limit: null,
        course_draft_count: assignedDrafts.length,
        credit_balance: licenses.filter((x) => x.available).length,
        plans: Object.values(COURSE_PLANS).sort((a, b) => a.number - b.number),
      },
      200,
      { "cache-control": "no-store" },
    );
  }
  const sales = await ctx.env.DB.prepare(
    `SELECT o.id,o.order_no,CASE WHEN o.course_plan='partner' THEN CAST(o.total / 2 AS INTEGER) ELSE o.total END total,o.total gross_total,o.course_plan,o.visiond_revenue,CASE WHEN o.course_plan='partner' THEN 0 ELSE o.course_api_fee END course_api_fee,o.updated_at paid_at,CASE WHEN o.slip_key IS NOT NULL AND TRIM(o.slip_key)<>'' THEN 1 ELSE 0 END has_slip,COALESCE((SELECT product_title FROM order_items WHERE order_id=o.id ORDER BY id LIMIT 1),p.title,'สินค้าเดิม') course_title,u.name buyer_name FROM orders o JOIN users u ON u.id=o.user_id LEFT JOIN products p ON p.id=(SELECT product_id FROM order_items WHERE order_id=o.id ORDER BY id LIMIT 1) WHERE o.course_owner_user_id=? AND o.status='paid' ORDER BY o.updated_at DESC LIMIT 200`,
  )
    .bind(auth.user.id)
    .all();
  const salesTotal = await ctx.env.DB.prepare(
    `SELECT COUNT(*) orders,COALESCE(SUM(CASE WHEN course_plan='partner' THEN CAST(total / 2 AS INTEGER) ELSE total END),0) amount FROM orders WHERE course_owner_user_id=? AND status='paid'`,
  )
    .bind(auth.user.id)
    .first();
  const issues = await ctx.env.DB.prepare(
    `SELECT o.id,o.order_no,o.total,o.slip_verification_code,o.updated_at,COALESCE((SELECT product_title FROM order_items WHERE order_id=o.id ORDER BY id LIMIT 1),p.title,'สินค้าเดิม') course_title,u.name buyer_name FROM orders o JOIN users u ON u.id=o.user_id LEFT JOIN products p ON p.id=(SELECT product_id FROM order_items WHERE order_id=o.id ORDER BY id LIMIT 1) WHERE o.course_owner_user_id=? AND o.status='pending_review' AND o.slip_key IS NOT NULL AND o.slip_verification_status='manual' ORDER BY o.updated_at DESC LIMIT 100`,
  )
    .bind(auth.user.id)
    .all();
  const items = courses.results || [],
    saleItems = sales.results || [],
    issueItems = issues.results || [],
    assignedDrafts = items.filter((x) => x.license_entitlement_id !== null);
  return json(
    {
      licenses,
      courses: items,
      sales: saleItems,
      sales_list_limited: saleItems.length >= 200,
      slip_issues: issueItems,
      totals: {
        amount: Number(salesTotal?.amount) || 0,
        orders: Number(salesTotal?.orders) || 0,
      },
      course_draft_limit: null,
      course_draft_count: assignedDrafts.length,
      credit_balance: licenses.filter((x) => x.available).length,
      plans:Object.values(COURSE_PLANS).sort((a,b)=>a.number-b.number),
    },
    200,
    { "cache-control": "no-store" },
  );
}
export async function onRequestPost(ctx) {
  await ensureDatabase(ctx.env);
  const auth = await requireUser(ctx);
  if (auth.error) return auth.error;
  const form=await ctx.request.formData(),selectedPlan=coursePlan(form.get('course_plan'));
  if(!selectedPlan||selectedPlan.code!=='partner')return json({error:'ปิดรับแผนซื้อสิทธิ์แล้ว กรุณาสร้างคอร์สพาร์ตเนอร์ 50/50',code:'COURSE_PLAN_CLOSED'},409);
  const title = String(form.get("title") || "").trim(),
    teacher = String(form.get("teacher_name") || "").trim(),
    description = String(form.get("description") || "").trim(),
    draftPrice = Math.round(Number(form.get("price_baht")) * 100);
  if (!title || !teacher || !description)
    return json(
      { error: "กรุณากรอกชื่อคอร์ส ชื่อผู้สอน และรายละเอียดให้ครบ" },
      400,
    );
  if (!Number.isFinite(draftPrice) || draftPrice < MIN_COURSE_PRICE_SATANG)
    return json({ error: coursePriceError() }, 400);
  const episodes = Number(form.get("expected_episodes"));
  if (!Number.isInteger(episodes) || episodes < 1 || episodes > 200)
    return json({ error: "จำนวน EP ต้องเป็นเลขจำนวนเต็ม 1–200" }, 400);
  let coverKey;
  try {
    coverKey = await putImage(ctx.env, form.get("cover"));
  } catch {
    return json(
      { error: "รูปปกต้องเป็น JPG, PNG หรือ WEBP ไม่เกิน 8 MB" },
      400,
    );
  }
  if (!coverKey) return json({ error: "กรุณาแนบรูปปกคอร์ส" }, 400);
  const allowed = new Set([
      "Shopee",
      "TikTok",
      "Lazada",
      "Kalodata",
      "YouTube",
      "Gemini",
      "Grok",
      "ChatGPT",
      "Facebook",
      "Canva",
      "อื่น ๆ",
    ]),
    tags = [
      ...new Set(
        form
          .getAll("platform_tags")
          .map(String)
          .filter((x) => allowed.has(x)),
      ),
    ],
    other = String(form.get("platform_other") || "")
      .trim()
      .slice(0, 60);
  if (tags.includes("อื่น ๆ") && other) tags.push(other);
  let slug = slugify(title),
    n = 1;
  while (
    await ctx.env.DB.prepare("SELECT id FROM products WHERE slug=?")
      .bind(slug)
      .first()
  )
    slug = `${slugify(title)}-${++n}`;
  const coverUrl = "/api/media/" + coverKey,
    short = String(form.get("short_description") || "").slice(0, 1000),
    contact = String(form.get("contact_info") || "")
      .trim()
      .slice(0, 200),
    level = ["beginner", "intermediate", "advanced", "all"].includes(
      String(form.get("learner_level")),
    )
      ? String(form.get("learner_level"))
      : "all";
  {
    try{
      const statements=[
        ctx.env.DB.prepare(`INSERT INTO products(slug,title,short_description,description,price,cover_url,preview_urls,category,file_type,pages,status,source,product_kind) VALUES(?,?,?,?,?,?,?,'online-course','คอร์สออนไลน์',?,'draft','user-course-draft','course')`).bind(slug,title,short,description,draftPrice,coverUrl,JSON.stringify([coverUrl]),episodes),
        ctx.env.DB.prepare(`INSERT INTO courses(product_id,subtitle,teacher_name,active,course_type,license_edit_days,owner_user_id,license_entitlement_id,edit_expires_at,contact_info,platform_tags,learner_level,expected_episodes,review_status,course_origin,basket_binding_locked,basket_bound_at,course_plan) SELECT id,?,?,0,'online_course',30,?,NULL,NULL,?,?,?,?,'draft','seller_rights',1,CURRENT_TIMESTAMP,? FROM products WHERE slug=?`).bind(short,teacher,auth.user.id,contact,JSON.stringify(tags),level,episodes,selectedPlan.code,slug)
      ];
      const results=await ctx.env.DB.batch(statements);if(!results[0].meta.changes||!results[1].meta.changes)throw new Error('COURSE_CREATE_FAILED');
      const course=await ctx.env.DB.prepare('SELECT c.id FROM courses c JOIN products p ON p.id=c.product_id WHERE p.slug=? AND c.owner_user_id=?').bind(slug,auth.user.id).first();
      return json({ok:true,id:course.id,slug,episode_count:episodes,course_plan:selectedPlan.code,credit_used:0,draft_only:false,message:'สร้างคอร์สพาร์ตเนอร์ 50/50 แล้ว'},201);
    }catch(error){await ctx.env.FILES.delete(coverKey).catch(()=>{});return json({error:'สร้างตะกร้าคอร์สไม่สำเร็จ กรุณาลองใหม่'},409)}
  }
}
