import {json} from '../../../_lib.js';import {ensureDatabase} from '../../../_schema.js';import {requireVision7User} from '../../../_vision7_auth.js';import {cleanConversationId,cleanMessageId,ensureVEasyRuntimeSchema,requireAppSession,verifyConversationLease} from '../../../_veasy_runtime.js';
export async function onRequestPost(ctx){await ensureDatabase(ctx.env);await ensureVEasyRuntimeSchema(ctx.env);const auth=await requireVision7User(ctx);if(auth.error)return auth.error;const appError=requireAppSession(auth.user);if(appError)return appError;const body=await ctx.request.json().catch(()=>({})),conversationId=cleanConversationId(body.conversation_id),messageId=cleanMessageId(body.platform_message_id);if(!conversationId||!messageId)return json({error:'ข้อมูลข้อความไม่ครบ',code:'VEASY_MESSAGE_CLAIM_INVALID'},400);const lease=await verifyConversationLease(ctx.env,auth.user,{shopId:body.shop_id,conversationId,leaseToken:body.conversation_lease_token});if(!lease)return json({error:'ต้องถือ Conversation Lease ก่อนประมวลผลข้อความ',code:'VEASY_CONVERSATION_LEASE_REQUIRED'},409);const result=await ctx.env.DB.prepare("INSERT OR IGNORE INTO veasy_message_claims(shop_id,platform_message_id,conversation_id) VALUES(?,?,?)").bind(lease.shop_id,messageId,conversationId).run();if(!result.meta?.changes){const existing=await ctx.env.DB.prepare('SELECT status,claimed_at,completed_at FROM veasy_message_claims WHERE shop_id=? AND platform_message_id=?').bind(lease.shop_id,messageId).first();return json({ok:true,duplicate:true,claim:existing},200,{'cache-control':'no-store'})}return json({ok:true,duplicate:false,status:'processing'},201,{'cache-control':'no-store'});}
export async function onRequestPatch(ctx){await ensureDatabase(ctx.env);await ensureVEasyRuntimeSchema(ctx.env);const auth=await requireVision7User(ctx);if(auth.error)return auth.error;const body=await ctx.request.json().catch(()=>({})),conversationId=cleanConversationId(body.conversation_id),messageId=cleanMessageId(body.platform_message_id);const lease=await verifyConversationLease(ctx.env,auth.user,{shopId:body.shop_id,conversationId,leaseToken:body.conversation_lease_token});if(!lease)return json({error:'Conversation Lease ไม่ถูกต้อง',code:'VEASY_CONVERSATION_LEASE_REQUIRED'},409);const result=await ctx.env.DB.prepare("UPDATE veasy_message_claims SET status='completed',completed_at=CURRENT_TIMESTAMP WHERE shop_id=? AND platform_message_id=? AND conversation_id=? AND status='processing'").bind(lease.shop_id,messageId,conversationId).run();return json({ok:Boolean(result.meta?.changes),completed:Boolean(result.meta?.changes)});}
