import {json,sha256} from '../../../_lib.js';import {ensureDatabase} from '../../../_schema.js';import {requireVision7User} from '../../../_vision7_auth.js';import {ensureVEasyShopSchema} from '../../../_veasy_shop.js';
export async function onRequestGet(ctx){await ensureDatabase(ctx.env);await ensureVEasyShopSchema(ctx.env);const auth=await requireVision7User(ctx);if(auth.error)return auth.error;const scope=await sha256(`veasy-account-scope-v1:${auth.user.id}`),shops=await ctx.env.DB.prepare('SELECT id,name,meta_page_id,status,updated_at FROM veasy_shops WHERE user_id=? ORDER BY updated_at DESC').bind(auth.user.id).all();return json({ok:true,account_scope_id:scope,clear_local_state_when_scope_changes:true,shops:shops.results||[]},200,{'cache-control':'no-store'});}
