import {json,requireAdmin} from '../../../../_lib.js';import {ensureDatabase} from '../../../../_schema.js';
export async function onRequestGet(ctx){await ensureDatabase(ctx.env);const auth=await requireAdmin(ctx);if(auth.error)return auth.error;const order=await ctx.env.DB.prepare('SELECT id,order_no FROM orders WHERE id=?').bind(ctx.params.id).first();if(!order)return json({error:'ไม่พบออเดอร์'},404);const rows=await ctx.env.DB.prepare('SELECT id,object_key,mime_type,file_size,source,note,created_at FROM order_slip_evidence WHERE order_id=? ORDER BY id').bind(order.id).all();return json({order_no:order.order_no,count:(rows.results||[]).length,items:(rows.results||[]).map(x=>({...x,object_key:undefined,url:`/api/admin/slip?key=${encodeURIComponent(x.object_key)}`}))},200,{'cache-control':'no-store'})}
