import {json} from '../../../../_lib.js';import {ensureDatabase} from '../../../../_schema.js';import {requireVision7User} from '../../../../_vision7_auth.js';import {cleanWebhookProvider,createWebhook,ensureWebhookHubSchema,mutateWebhook,projectWebhook} from '../../../../_webhook_hub.js';
const ns={'cache-control':'private, no-store'};async function owner(ctx,user){return ctx.env.DB.prepare('SELECT id FROM veasy_shops WHERE id=? AND user_id=?').bind(ctx.params.shopId,user.id).first()}
export async function onRequestGet(ctx){await ensureDatabase(ctx.env);await ensureWebhookHubSchema(ctx.env);const a=await requireVision7User(ctx);if(a.error)return a.error;if(!await owner(ctx,a.user))return json({error:'ไม่พบร้านที่เป็นเจ้าของ'},404,ns);const r=await ctx.env.DB.prepare('SELECT * FROM veasy_webhook_endpoints WHERE shop_id=? ORDER BY updated_at DESC').bind(ctx.params.shopId).all();return json({items:(r.results||[]).map(x=>projectWebhook(ctx.env,x))},200,ns)}
export async function onRequestPost(ctx){await ensureDatabase(ctx.env);await ensureWebhookHubSchema(ctx.env);const a=await requireVision7User(ctx);if(a.error)return a.error;if(!await owner(ctx,a.user))return json({error:'ไม่พบร้านที่เป็นเจ้าของ'},404,ns);const b=await ctx.request.json().catch(()=>({})),p=cleanWebhookProvider(b.provider);if(!p)return json({error:'Provider ไม่ถูกต้อง'},400,ns);try{return json({item:projectWebhook(ctx.env,await createWebhook(ctx.env,{shopId:ctx.params.shopId,provider:p,actorId:a.user.id}))},201,ns)}catch{return json({error:'ร้านนี้มีลิงก์ Provider นี้อยู่แล้ว'},409,ns)}}
export async function onRequestPatch(ctx){await ensureDatabase(ctx.env);await ensureWebhookHubSchema(ctx.env);const a=await requireVision7User(ctx);if(a.error)return a.error;if(!await owner(ctx,a.user))return json({error:'ไม่พบร้านที่เป็นเจ้าของ'},404,ns);const b=await ctx.request.json().catch(()=>({}));try{const x=await mutateWebhook(ctx.env,{id:String(b.id||''),shopId:ctx.params.shopId,action:String(b.action||'')});return x?json({item:projectWebhook(ctx.env,x)},200,ns):json({error:'ไม่พบลิงก์'},404,ns)}catch{return json({error:'คำสั่งไม่ถูกต้อง'},400,ns)}}
