import {json,sha256} from '../../../_lib.js';import {ensureDatabase} from '../../../_schema.js';import {requireVision7User} from '../../../_vision7_auth.js';import {acquireRuntimeLease,ensureVEasyRuntimeSchema,requireAppSession,verifyRuntimeLease} from '../../../_veasy_runtime.js';
export async function onRequestPost(ctx){await ensureDatabase(ctx.env);await ensureVEasyRuntimeSchema(ctx.env);const auth=await requireVision7User(ctx);if(auth.error)return auth.error;const appError=requireAppSession(auth.user);if(appError)return appError;const body=await ctx.request.json().catch(()=>({})),result=await acquireRuntimeLease(ctx.env,auth.user,body.shop_id);if(result.error)return json({error:result.error,code:result.code,expires_at:result.expires_at},result.status);return json(result,201,{'cache-control':'no-store'});}
export async function onRequestPatch(ctx){await ensureDatabase(ctx.env);await ensureVEasyRuntimeSchema(ctx.env);const auth=await requireVision7User(ctx);if(auth.error)return auth.error;const body=await ctx.request.json().catch(()=>({})),lease=await verifyRuntimeLease(ctx.env,auth.user,body.shop_id,body.lease_token);if(!lease)return json({error:'Runtime Lease หมดอายุหรือไม่ใช่ของเครื่องนี้',code:'VEASY_RUNTIME_LEASE_INVALID'},409);await ctx.env.DB.prepare("UPDATE veasy_runtime_leases SET heartbeat_at=CURRENT_TIMESTAMP,expires_at=datetime('now','+45 seconds') WHERE shop_id=? AND app_session_id=? AND lease_token_hash=?").bind(lease.shop_id,auth.user.vision7_session_id,await sha256(String(body.lease_token||''))).run();return json({ok:true,expires_in:45});}
export async function onRequestDelete(ctx){await ensureDatabase(ctx.env);await ensureVEasyRuntimeSchema(ctx.env);const auth=await requireVision7User(ctx);if(auth.error)return auth.error;const body=await ctx.request.json().catch(()=>({})),lease=await verifyRuntimeLease(ctx.env,auth.user,body.shop_id,body.lease_token);if(lease)await ctx.env.DB.prepare('DELETE FROM veasy_runtime_leases WHERE shop_id=? AND app_session_id=?').bind(lease.shop_id,auth.user.vision7_session_id).run();return json({ok:true});}
