import {json,requireBoss} from '../../../_lib.js';import {ensureDatabase} from '../../../_schema.js';import {ensureVision14Schema} from '../../../_vision14.js';const headers={'cache-control':'private, no-store'},parse=value=>{try{return JSON.parse(value||'[]')}catch{return[]}};
export async function onRequestGet(ctx){await ensureDatabase(ctx.env);await ensureVision14Schema(ctx.env);const a=await requireBoss(ctx);if(a.error)return a.error;const mix=await ctx.env.DB.prepare(`SELECT m.*,(SELECT q.status FROM vision13_intake_queue q WHERE q.mix_id=m.id) vision13_status FROM vision14_mixes m WHERE m.id=?`).bind(ctx.params.id).first();if(!mix)return json({error:'ไม่พบ MIX'},404,headers);const sources=(await ctx.env.DB.prepare(`SELECT s.source_id,v.title,s.rights_status,s.sale_eligible FROM vision14_mix_sources s JOIN vision14_sources v ON v.id=s.source_id WHERE s.mix_id=? ORDER BY v.title`).bind(mix.id).all()).results||[],items=(await ctx.env.DB.prepare('SELECT id,canonical_text,fingerprint,citations FROM vision14_mix_items WHERE mix_id=? ORDER BY id').bind(mix.id).all()).results||[];return json({mix,sources,items:items.map(item=>({...item,citations:parse(item.citations)}))},200,headers)}
