import {json,requireAdmin} from '../../../../_lib.js';import {ensureDatabase} from '../../../../_schema.js';
export async function onRequestGet(ctx){await ensureDatabase(ctx.env);const auth=await requireAdmin(ctx);if(auth.error)return auth.error;const user=await ctx.env.DB.prepare('SELECT seller_payment_qr_url FROM users WHERE id=?').bind(ctx.params.id).first();if(!user?.seller_payment_qr_url)return json({error:'ไม่พบ QR'},404);const object=await ctx.env.FILES.get(user.seller_payment_qr_url);if(!object)return json({error:'ไม่พบไฟล์ QR'},404);const headers=new Headers();object.writeHttpMetadata(headers);headers.set('cache-control','private, no-store');return new Response(object.body,{headers})}
