const enc=new TextEncoder(),dec=new TextDecoder(),AAD=enc.encode('visiond-channel-credentials-v1'),PREFIX='vdch1:';
const b64=a=>btoa(String.fromCharCode(...a)),unb64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
async function key(env){const secret=String(env.VISIOND_CHANNEL_ENCRYPTION_KEY||'');if(secret.length<32)throw new Error('CHANNEL_ENCRYPTION_NOT_CONFIGURED');const digest=await crypto.subtle.digest('SHA-256',enc.encode(secret));return crypto.subtle.importKey('raw',digest,{name:'AES-GCM'},false,['encrypt','decrypt'])}
export const channelEncryptionReady=env=>String(env.VISIOND_CHANNEL_ENCRYPTION_KEY||'').length>=32;
export async function encryptChannelValue(env,value){const iv=crypto.getRandomValues(new Uint8Array(12)),data=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:AAD},await key(env),enc.encode(String(value)));return `${PREFIX}${b64(iv)}:${b64(new Uint8Array(data))}`}
export async function decryptChannelValue(env,value){const parts=String(value||'').slice(PREFIX.length).split(':');if(parts.length!==2)throw new Error('CHANNEL_CIPHERTEXT_INVALID');const data=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(parts[0]),additionalData:AAD},await key(env),unb64(parts[1]));return dec.decode(data)}
export async function lineSignatureValid(secret,raw,signature){const k=await crypto.subtle.importKey('raw',enc.encode(secret),{name:'HMAC',hash:'SHA-256'},false,['sign']),mac=new Uint8Array(await crypto.subtle.sign('HMAC',k,enc.encode(raw))),expected=b64(mac),a=enc.encode(expected),b=enc.encode(String(signature||''));if(a.length!==b.length)return false;let diff=0;for(let i=0;i<a.length;i++)diff|=a[i]^b[i];return diff===0}
