import {json,requireAdmin} from '../../_lib.js';
import {decryptChannelValue} from '../../_channel_crypto.js';

const headers={'cache-control':'private, no-store'},clean=(value,max=4900)=>String(value||'').replace(/[\u0000-\u001f\u007f]/g,' ').trim().replace(/\s+/g,' ').slice(0,max);
async function authorize(ctx){const auth=await requireAdmin(ctx);return auth.error?{error:auth.error}:auth}
const origin=env=>{try{const value=new URL(env.APP_ORIGIN||'https://visiondonline.com');return value.protocol==='https:'?value.origin:'https://visiondonline.com'}catch{return 'https://visiondonline.com'}};

export async function onRequestGet(ctx){const auth=await authorize(ctx);if(auth.error)return auth.error;const url=new URL(ctx.request.url),shopId=clean(url.searchParams.get('shop_id'),80),conversationId=clean(url.searchParams.get('conversation_id'),160),platform=['line','facebook'].includes(url.searchParams.get('platform'))?url.searchParams.get('platform'):'';if(conversationId&&shopId){const conversation=await ctx.env.DB.prepare(`SELECT c.id,c.shop_id,c.display_name,c.profile_url,c.platform,c.updated_at,s.name shop_name,COALESCE(k.mode,'bot') mode FROM veasy_conversations c JOIN veasy_shops s ON s.id=c.shop_id LEFT JOIN veasy_conversation_controls k ON k.shop_id=c.shop_id AND k.conversation_id=c.id WHERE c.shop_id=? AND c.id=?`).bind(shopId,conversationId).first();if(!conversation)return json({error:'ไม่พบบทสนทนา'},404,headers);const messages=(await ctx.env.DB.prepare(`SELECT id,role,content,message_type,media_url,media_mime,created_at FROM veasy_chat_messages WHERE shop_id=? AND conversation_id=? ORDER BY created_at ASC LIMIT 300`).bind(shopId,conversationId).all()).results||[];return json({conversation,messages},200,headers)}const rows=(await ctx.env.DB.prepare(`SELECT c.id,c.shop_id,c.display_name,c.profile_url,c.platform,c.updated_at,s.name shop_name,COALESCE(k.mode,'bot') mode,(SELECT content FROM veasy_chat_messages m WHERE m.shop_id=c.shop_id AND m.conversation_id=c.id ORDER BY m.created_at DESC LIMIT 1) last_message,(SELECT message_type FROM veasy_chat_messages m WHERE m.shop_id=c.shop_id AND m.conversation_id=c.id ORDER BY m.created_at DESC LIMIT 1) last_message_type FROM veasy_conversations c JOIN veasy_shops s ON s.id=c.shop_id LEFT JOIN veasy_conversation_controls k ON k.shop_id=c.shop_id AND k.conversation_id=c.id WHERE c.status='active' AND (?='' OR c.platform=?) ORDER BY c.updated_at DESC LIMIT 200`).bind(platform,platform).all()).results||[];return json({conversations:rows,channels:{line:true,facebook:rows.some(x=>x.platform==='facebook')}},200,headers)}

export async function onRequestPatch(ctx){const auth=await authorize(ctx);if(auth.error)return auth.error;const body=await ctx.request.json().catch(()=>({})),shopId=clean(body.shop_id,80),conversationId=clean(body.conversation_id,160),mode=body.mode==='human'?'human':body.mode==='bot'?'bot':'';if(!shopId||!conversationId||!mode)return json({error:'ข้อมูลรับช่วงไม่ครบ'},400,headers);const result=await ctx.env.DB.prepare('UPDATE veasy_conversation_controls SET mode=?,updated_at=CURRENT_TIMESTAMP WHERE shop_id=? AND conversation_id=?').bind(mode,shopId,conversationId).run();if(!result.meta?.changes)return json({error:'ไม่พบบทสนทนา'},404,headers);return json({ok:true,mode},200,headers)}

export async function onRequestPost(ctx){const auth=await authorize(ctx);if(auth.error)return auth.error;const form=await ctx.request.formData(),shopId=clean(form.get('shop_id'),80),conversationId=clean(form.get('conversation_id'),160),text=clean(form.get('text')),image=form.get('image');if(!shopId||!conversationId||(!text&&(!image||!image.size)))return json({error:'กรุณาพิมพ์ข้อความหรือแนบรูป'},400,headers);const row=await ctx.env.DB.prepare(`SELECT c.platform,COALESCE(k.mode,'bot') mode,k.target_ciphertext,x.token_ciphertext FROM veasy_conversations c LEFT JOIN veasy_conversation_controls k ON k.shop_id=c.shop_id AND k.conversation_id=c.id LEFT JOIN veasy_channel_credentials x ON x.shop_id=c.shop_id AND x.provider=c.platform WHERE c.shop_id=? AND c.id=?`).bind(shopId,conversationId).first();if(!row)return json({error:'ไม่พบบทสนทนา'},404,headers);if(row.mode!=='human')return json({error:'กด “V12 รับช่วง” ก่อนส่งข้อความ'},409,headers);if(row.platform==='facebook'){const facebook=await ctx.env.DB.prepare("SELECT token_ciphertext,external_account_id FROM v12_channel_credentials WHERE provider='facebook' AND verified_at IS NOT NULL").first();row.token_ciphertext=facebook?.token_ciphertext||'';row.page_id=facebook?.external_account_id||''}if(!row.token_ciphertext||!row.target_ciphertext)return json({error:`ช่องทาง ${row.platform==='line'?'LINE':'Facebook'} ยังเชื่อมต่อไม่ครบ`},409,headers);const messages=[];if(text)messages.push({type:'text',text});let mediaUrl='',mediaMime='';if(image&&image.size){if(!['image/jpeg','image/png'].includes(image.type)||image.size>1024*1024)return json({error:'รูปต้องเป็น JPG หรือ PNG ไม่เกิน 1 MB'},400,headers);mediaMime=image.type;const key=`v12-connect/outbound/${shopId}/${crypto.randomUUID()}.${image.type==='image/png'?'png':'jpg'}`;await ctx.env.FILES.put(key,await image.arrayBuffer(),{httpMetadata:{contentType:image.type}});mediaUrl=`/api/media/${key}`;const absolute=`${origin(ctx.env)}${mediaUrl}`;messages.push({type:'image',originalContentUrl:absolute,previewImageUrl:absolute})}try{const [token,target]=await Promise.all([decryptChannelValue(ctx.env,row.token_ciphertext),decryptChannelValue(ctx.env,row.target_ciphertext)]),retryKey=crypto.randomUUID();let response;if(row.platform==='line')response=await fetch('https://api.line.me/v2/bot/message/push',{method:'POST',headers:{authorization:`Bearer ${token}`,'content-type':'application/json','x-line-retry-key':retryKey},body:JSON.stringify({to:target,messages})});else{let payload;if(mediaUrl){const upload=new FormData();upload.set('message',JSON.stringify({attachment:{type:'image',payload:{is_reusable:true}}}));upload.set('filedata',image,image.name||'image.jpg');const uploaded=await fetch(`https://graph.facebook.com/${encodeURIComponent(row.page_id)}/message_attachments?access_token=${encodeURIComponent(token)}`,{method:'POST',body:upload}),uploadedData=await uploaded.json().catch(()=>({}));if(!uploaded.ok||!uploadedData.attachment_id)throw new Error(`FACEBOOK_UPLOAD_HTTP_${uploaded.status}_${clean(uploadedData?.error?.code||'',20)}`);payload={recipient:{id:target},message:{attachment:{type:'image',payload:{attachment_id:uploadedData.attachment_id}}},messaging_type:'RESPONSE'}}else payload={recipient:{id:target},message:{text},messaging_type:'RESPONSE'};response=await fetch(`https://graph.facebook.com/me/messages?access_token=${encodeURIComponent(token)}`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)})}if(!response.ok){const providerError=await response.json().catch(()=>({})),providerCode=clean(providerError?.error?.code||providerError?.message||'',40);throw new Error(`${row.platform.toUpperCase()}_PUSH_HTTP_${response.status}${providerCode?`_${providerCode}`:''}`)}const writes=[];if(text)writes.push(ctx.env.DB.prepare(`INSERT INTO veasy_chat_messages(id,shop_id,conversation_id,platform_message_id,role,content,message_type) VALUES(?,?,?,?, 'assistant',?,'text')`).bind(crypto.randomUUID(),shopId,conversationId,`v12:${retryKey}:text`,text));if(mediaUrl)writes.push(ctx.env.DB.prepare(`INSERT INTO veasy_chat_messages(id,shop_id,conversation_id,platform_message_id,role,content,message_type,media_url,media_mime) VALUES(?,?,?,?, 'assistant','[รูปภาพ]','image',?,?)`).bind(crypto.randomUUID(),shopId,conversationId,`v12:${retryKey}:image`,mediaUrl,mediaMime));writes.push(ctx.env.DB.prepare('UPDATE veasy_conversations SET updated_at=CURRENT_TIMESTAMP WHERE shop_id=? AND id=?').bind(shopId,conversationId));await ctx.env.DB.batch(writes);return json({ok:true},200,headers)}catch(error){console.error('V12_CONNECT_SEND_FAILED',{shopId,conversationId,error:clean(error?.message,100)});return json({error:`ส่ง ${row.platform==='line'?'LINE':'Facebook'} ไม่สำเร็จ`,code:'V12_CONNECT_SEND_FAILED',detail:clean(error?.message,100)},502,headers)}}
