import {json,requireBoss} from '../../../_lib.js';import {ensureDatabase} from '../../../_schema.js';import {ensureVision14Schema} from '../../../_vision14.js';import {buildVision13Epub,sha256} from '../../../_vision13_epub.js';const headers={'cache-control':'private, no-store'},parse=value=>{try{return JSON.parse(value||'[]')}catch{return[]}};
async function auth(ctx){await ensureDatabase(ctx.env);await ensureVision14Schema(ctx.env);return requireBoss(ctx)}
async function approved(env,id){const queue=await env.DB.prepare(`SELECT q.id,q.mix_id,q.status,m.title,m.internal_only FROM vision13_intake_queue q JOIN vision14_mixes m ON m.id=q.mix_id WHERE q.id=?`).bind(id).first();if(!queue)return null;const review=await env.DB.prepare("SELECT snapshot_hash FROM vision13_intake_reviews WHERE queue_id=? AND action='approve' AND snapshot_hash!='' ORDER BY id DESC LIMIT 1").bind(queue.id).first(),items=(await env.DB.prepare('SELECT id,canonical_text,fingerprint,citations FROM vision14_mix_items WHERE mix_id=? ORDER BY id').bind(queue.mix_id).all()).results||[];return{queue,review,items:items.map(item=>({...item,citations:parse(item.citations)}))}}
export async function onRequestGet(ctx){const a=await auth(ctx);if(a.error)return a.error;const row=await ctx.env.DB.prepare('SELECT * FROM vision13_ebook_productions WHERE queue_id=?').bind(ctx.params.id).first();if(!row)return json({error:'ยังไม่ได้ผลิต E-book'},404,headers);const object=await ctx.env.FILES.get(row.object_key);if(!object)return json({error:'ไม่พบไฟล์ E-book ในพื้นที่จัดเก็บ'},404,headers);return new Response(object.body,{headers:{...headers,'content-type':'application/epub+zip','content-disposition':`attachment; filename="vision13-${row.id}.epub"`,'content-length':String(row.file_size),'x-content-type-options':'nosniff'}})}
export async function onRequestPost(ctx){const a=await auth(ctx);if(a.error)return a.error;if(!ctx.env.FILES)return json({error:'ยังไม่ได้เชื่อม R2 FILES'},503,headers);const result=await approved(ctx.env,ctx.params.id);if(!result)return json({error:'ไม่พบงาน Intake'},404,headers);if(result.queue.status!=='approved')return json({error:'ผลิตได้เฉพาะงานที่อนุมัติแล้ว'},409,headers);if(result.queue.internal_only||!result.review?.snapshot_hash)return json({error:'ไม่พบ Approval Snapshot ที่ใช้ผลิต'},409,headers);if(!result.items.length||result.items.some(item=>item.fingerprint.length!==64||!item.citations.length))return json({error:'ข้อมูลผลิตไม่ครบ'},409,headers);const current=await sha256(result.items.map(item=>`${item.id}:${item.fingerprint}:${JSON.stringify(item.citations)}`).join('|'));if(current!==result.review.snapshot_hash)return json({error:'MIX เปลี่ยนหลังอนุมัติ กรุณาตีกลับและตรวจใหม่',code:'APPROVAL_SNAPSHOT_MISMATCH'},409,headers);const existing=await ctx.env.DB.prepare('SELECT id,artifact_hash,file_size FROM vision13_ebook_productions WHERE queue_id=?').bind(result.queue.id).first();if(existing)return json({ok:true,already_produced:true,...existing},200,headers);const id=`ebook_${crypto.randomUUID().replaceAll('-','')}`,epub=buildVision13Epub({id,title:result.queue.title,items:result.items}),artifact=await sha256(epub),key=`vision13/ebooks/${id}.epub`;await ctx.env.FILES.put(key,epub,{httpMetadata:{contentType:'application/epub+zip'},customMetadata:{queueId:String(result.queue.id),approvalSnapshot:current,artifactHash:artifact}});try{await ctx.env.DB.batch([ctx.env.DB.prepare(`INSERT INTO vision13_ebook_productions(id,queue_id,mix_id,approval_snapshot_hash,artifact_hash,object_key,file_size,item_count,produced_by) VALUES(?,?,?,?,?,?,?,?,?)`).bind(id,result.queue.id,result.queue.mix_id,current,artifact,key,epub.length,result.items.length,a.user.id),ctx.env.DB.prepare("UPDATE vision13_intake_queue SET status='produced',updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='approved'").bind(result.queue.id),ctx.env.DB.prepare("UPDATE vision14_mixes SET status='vision13_produced',updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(result.queue.mix_id),ctx.env.DB.prepare("INSERT INTO vision13_intake_reviews(queue_id,action,note,snapshot_hash,reviewed_by) VALUES(?,'produce','สร้างไฟล์ EPUB จาก Approval Snapshot',?,?)").bind(result.queue.id,current,a.user.id)])}catch(error){await ctx.env.FILES.delete(key);throw error}return json({ok:true,id,artifact_hash:artifact,file_size:epub.length,item_count:result.items.length},201,headers)}
