import {json,requireBoss} from '../../../_lib.js';import {ensureDatabase} from '../../../_schema.js';import {ensureVision14Schema} from '../../../_vision14.js';const headers={'cache-control':'private, no-store'},parse=value=>{try{return JSON.parse(value||'[]')}catch{return[]}};
async function auth(ctx){await ensureDatabase(ctx.env);await ensureVision14Schema(ctx.env);return requireBoss(ctx)}
const sentences=text=>String(text||'').split(/(?<=[.!?。！？]|ครับ|ค่ะ)\s+|\n+/u).map(value=>value.replace(/\s+/g,' ').trim()).filter(value=>value.length>=18);
function keywords(pages){const stop=new Set(['และ','หรือ','ของ','ที่','ใน','เป็น','การ','จาก','ให้','กับ','มี','ได้','จะ','เพื่อ','โดย','the','and','for','with','this','that','from']);const counts=new Map();for(const page of pages)for(const word of page.clean_text.toLowerCase().match(/[\p{L}\p{N}]{3,}/gu)||[])if(!stop.has(word))counts.set(word,(counts.get(word)||0)+1);return [...counts].sort((a,b)=>b[1]-a[1]).slice(0,20).map(([word,count])=>({word,count}))}
function summarize(pages){const total=Math.max(...pages.map(page=>Number(page.page_number))),missing=[];for(let page=1;page<=total;page++)if(!pages.some(item=>Number(item.page_number)===page&&item.extraction_status==='success'&&item.clean_text.trim()))missing.push(page);const clean=pages.filter(page=>page.extraction_status==='success'&&page.clean_text.trim()),size=Math.max(1,Math.ceil(clean.length/10)),sections=[];for(let index=0;index<clean.length;index+=size){const group=clean.slice(index,index+size),chosen=group.flatMap(page=>sentences(page.clean_text).slice(0,2).map(text=>({text,page:Number(page.page_number)}))).slice(0,8);if(chosen.length)sections.push({title:`เนื้อหาหน้า ${group[0].page_number}–${group.at(-1).page_number}`,page_start:Number(group[0].page_number),page_end:Number(group.at(-1).page_number),points:chosen})}const overview=sections.slice(0,4).flatMap(section=>section.points.slice(0,1).map(point=>point.text)).join(' ').slice(0,3000);return{overview,sections,keywords:keywords(clean),covered_pages:clean.length,total_pages:total,missing_pages:missing}}
export async function onRequestGet(ctx){const a=await auth(ctx);if(a.error)return a.error;const source=await ctx.env.DB.prepare('SELECT id,title,rights_status,processing_status FROM vision14_sources WHERE id=?').bind(ctx.params.id).first();if(!source)return json({error:'ไม่พบต้นฉบับ'},404,headers);const item=await ctx.env.DB.prepare('SELECT * FROM vision14_book_summaries WHERE source_id=?').bind(source.id).first();return json({source,item:item?{...item,sections:parse(item.sections),keywords:parse(item.keywords),missing_pages:parse(item.missing_pages)}:null},200,headers)}
export async function onRequestPost(ctx){const a=await auth(ctx);if(a.error)return a.error;const source=await ctx.env.DB.prepare('SELECT id,title FROM vision14_sources WHERE id=?').bind(ctx.params.id).first();if(!source)return json({error:'ไม่พบต้นฉบับ'},404,headers);const pages=(await ctx.env.DB.prepare('SELECT page_number,clean_text,extraction_status FROM vision14_source_pages WHERE source_id=? ORDER BY page_number').bind(source.id).all()).results||[];if(!pages.some(page=>page.extraction_status==='success'&&page.clean_text.trim()))return json({error:'ยังไม่มีข้อความสะอาดสำหรับสรุป'},409,headers);const result=summarize(pages);await ctx.env.DB.prepare(`INSERT INTO vision14_book_summaries(source_id,overview,sections,keywords,covered_pages,total_pages,missing_pages,summary_method,created_by) VALUES(?,?,?,?,?,?,?,'extractive',?) ON CONFLICT(source_id) DO UPDATE SET overview=excluded.overview,sections=excluded.sections,keywords=excluded.keywords,covered_pages=excluded.covered_pages,total_pages=excluded.total_pages,missing_pages=excluded.missing_pages,summary_method=excluded.summary_method,updated_at=CURRENT_TIMESTAMP`).bind(source.id,result.overview,JSON.stringify(result.sections),JSON.stringify(result.keywords),result.covered_pages,result.total_pages,JSON.stringify(result.missing_pages),a.user.id).run();await ctx.env.DB.prepare("UPDATE vision14_sources SET processing_status='summarized',updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(source.id).run();return json({ok:true,...result,summary_method:'extractive'},200,headers)}
