import {json,requireBoss} from '../../../../_lib.js';
import {ensureDatabase} from '../../../../_schema.js';
import {decryptPartnerData} from '../../../../_partner_crypto.js';
import {ensurePartnerSyncReady as ensurePartnerSyncSchema} from '../../../../_partner_sync.js';
const headers={'cache-control':'private, no-store'};
export async function onRequestGet(ctx){await ensureDatabase(ctx.env);await ensurePartnerSyncSchema(ctx.env);const auth=await requireBoss(ctx);if(auth.error)return auth.error;const website=await ctx.env.DB.prepare('SELECT id,name,domain,status FROM partner_websites WHERE id=?').bind(ctx.params.id).first();if(!website)return json({error:'ไม่พบเว็บไซต์คู่ค้า'},404,headers);const [stats,customerRows,orderRows]=await Promise.all([ctx.env.DB.prepare(`SELECT (SELECT COUNT(*) FROM partner_customers WHERE website_id=?) customers,(SELECT COUNT(*) FROM partner_orders WHERE website_id=?) orders,(SELECT COALESCE(SUM(total-refunded_amount),0) FROM partner_orders WHERE website_id=? AND payment_status IN ('paid','partially_refunded','refunded')) net_sales,(SELECT COALESCE(SUM(refunded_amount),0) FROM partner_orders WHERE website_id=?) refunded`).bind(website.id,website.id,website.id,website.id).first(),ctx.env.DB.prepare('SELECT id,external_customer_id,profile_ciphertext,status,external_created_at,last_synced_at FROM partner_customers WHERE website_id=? ORDER BY updated_at DESC LIMIT 100').bind(website.id).all(),ctx.env.DB.prepare(`SELECT o.id,o.external_order_id,o.external_customer_id,o.status,o.payment_status,o.currency,o.subtotal,o.discount,o.total,o.refunded_amount,o.external_created_at,o.external_updated_at,(SELECT COUNT(*) FROM partner_order_items i WHERE i.order_id=o.id) item_count FROM partner_orders o WHERE o.website_id=? ORDER BY o.updated_at DESC LIMIT 100`).bind(website.id).all()]),customers=[];for(const row of customerRows.results||[]){let profile={name:'[อ่านข้อมูลไม่ได้]',email:'',phone:''};try{profile=JSON.parse(await decryptPartnerData(ctx.env,row.profile_ciphertext))}catch{}customers.push({id:row.id,external_customer_id:row.external_customer_id,status:row.status,name:profile.name||'',email:profile.email||'',phone:profile.phone||'',external_created_at:row.external_created_at,last_synced_at:row.last_synced_at})}return json({website,stats:{customers:Number(stats?.customers)||0,orders:Number(stats?.orders)||0,net_sales:Number(stats?.net_sales)||0,refunded:Number(stats?.refunded)||0},customers,orders:orderRows.results||[]},200,headers)}
