import {json,requireBoss} from '../../../_lib.js';import {ensureDatabase} from '../../../_schema.js';import {ensureVision14Schema} from '../../../_vision14.js';const headers={'cache-control':'private, no-store'};
export async function onRequestGet(ctx){await ensureDatabase(ctx.env);await ensureVision14Schema(ctx.env);const a=await requireBoss(ctx);if(a.error)return a.error;const items=(await ctx.env.DB.prepare(`SELECT q.id queue_id,q.mix_id,q.status,q.attempts,q.last_error,q.created_at,q.updated_at,m.title,m.item_count,m.duplicate_count,m.internal_only,(SELECT COUNT(*) FROM vision14_mix_sources s WHERE s.mix_id=m.id) source_count,(SELECT r.note FROM vision13_intake_reviews r WHERE r.queue_id=q.id ORDER BY r.id DESC LIMIT 1) latest_note,(SELECT r.created_at FROM vision13_intake_reviews r WHERE r.queue_id=q.id ORDER BY r.id DESC LIMIT 1) reviewed_at,p.id production_id,p.artifact_hash,p.file_size production_file_size,p.created_at produced_at FROM vision13_intake_queue q JOIN vision14_mixes m ON m.id=q.mix_id LEFT JOIN vision13_ebook_productions p ON p.queue_id=q.id ORDER BY CASE q.status WHEN 'ready' THEN 1 WHEN 'reviewing' THEN 2 WHEN 'rejected' THEN 3 WHEN 'approved' THEN 4 WHEN 'produced' THEN 5 ELSE 6 END,q.created_at`).all()).results||[];return json({items},200,headers)}
