import {json,requireAdmin} from '../../_lib.js';import {ensureDatabase} from '../../_schema.js';import {ensureVision7Schema} from '../../_vision7_schema.js';
const date=v=>/^\d{4}-\d{2}-\d{2}$/.test(String(v||''))?String(v):null,num=v=>Number(v)||0;
export async function onRequestGet(ctx){await ensureDatabase(ctx.env);await ensureVision7Schema(ctx.env);const a=await requireAdmin(ctx);if(a.error)return a.error;const u=new URL(ctx.request.url),to=date(u.searchParams.get('to'))||new Date().toISOString().slice(0,10),from=date(u.searchParams.get('from'))||new Date(Date.now()-29*86400000).toISOString().slice(0,10);if(from>to)return json({error:'ช่วงวันที่ไม่ถูกต้อง'},400);const rows=await ctx.env.DB.prepare(`WITH costs AS (SELECT 'facebook' platform,campaign_name campaign,adset_name adset,COALESCE(NULLIF(creative_name,''),ad_name) creative,SUM(spend) cost,SUM(impressions) impressions,SUM(clicks) clicks FROM meta_ads_insights WHERE insight_date BETWEEN ? AND ? GROUP BY campaign_id,adset_id,ad_id UNION ALL SELECT c.platform,c.campaign,c.adset,c.creative,SUM(c.cost),0,0 FROM ad_campaign_costs c WHERE c.spend_date BETWEEN ? AND ? AND NOT EXISTS(SELECT 1 FROM meta_ads_insights m WHERE m.insight_date=c.spend_date AND m.campaign_name=c.campaign AND (m.creative_name=c.creative OR m.ad_name=c.creative)) GROUP BY c.platform,c.campaign,c.adset,c.creative) SELECT c.platform,c.campaign,c.adset,c.creative,SUM(c.cost) spend,SUM(c.impressions) impressions,SUM(c.clicks) clicks,COUNT(DISTINCT o.id) orders,COALESCE(SUM(DISTINCT CASE WHEN o.status='paid' THEN o.total ELSE 0 END),0) revenue FROM costs c LEFT JOIN customer_events e ON e.campaign=c.campaign AND (e.content=c.creative OR c.creative='') AND e.event_type='purchase' LEFT JOIN orders o ON o.id=e.order_id AND o.status='paid' GROUP BY c.platform,c.campaign,c.adset,c.creative ORDER BY spend DESC`).bind(from,to,from,to).all(),items=(rows.results||[]).map(r=>{const spend=num(r.spend),revenue=num(r.revenue),roas=spend?revenue/spend:null,ctr=num(r.impressions)?num(r.clicks)/num(r.impressions)*100:null;let decision='observe',reason='ข้อมูลยังไม่พอ ควรเก็บข้อมูลต่อ';if(spend>0&&revenue===0){decision='stop_or_adjust';reason='มีค่าใช้จ่ายแต่ยังไม่พบยอดขายที่ระบุแหล่งที่มา'}else if(roas>=2){decision='continue';reason='ROAS ตั้งแต่ 2 เท่าขึ้นไป'}else if(roas!==null&&roas<1){decision='adjust';reason='รายได้ต่ำกว่าค่าโฆษณา'}return {...r,spend,revenue,orders:num(r.orders),impressions:num(r.impressions),clicks:num(r.clicks),ctr,roas,profit:revenue-spend,decision,reason}});const summary=items.reduce((s,x)=>({spend:s.spend+x.spend,revenue:s.revenue+x.revenue,orders:s.orders+x.orders,impressions:s.impressions+x.impressions,clicks:s.clicks+x.clicks}),{spend:0,revenue:0,orders:0,impressions:0,clicks:0});summary.profit=summary.revenue-summary.spend;summary.roas=summary.spend?summary.revenue/summary.spend:null;summary.ctr=summary.impressions?summary.clicks/summary.impressions*100:null;const page=await ctx.env.DB.prepare(`SELECT COUNT(*) conversations,SUM(status='human_required') handoff_waiting FROM elon_page_conversations WHERE date(created_at,'+7 hours') BETWEEN ? AND ?`).bind(from,to).first(),sync=await ctx.env.DB.prepare(`SELECT status,rows_synced,error_code,started_at,completed_at,date_from,date_to FROM meta_ads_sync_runs ORDER BY started_at DESC LIMIT 1`).first();return json({from,to,summary,page_sales:page,items,sync,note:'ข้อมูล Meta Ads มาจาก API เมื่อซิงก์สำเร็จ รายการกรอกมือใช้เฉพาะวันที่/ชื่อที่ยังไม่มีข้อมูล API และระบบไม่แก้ไขโฆษณาอัตโนมัติ'},200,{'cache-control':'no-store'});}
