import {json,requireBoss} from '../../../../_lib.js';import {ensureDatabase} from '../../../../_schema.js';import {ensureVision14Schema} from '../../../../_vision14.js';
export async function onRequestGet(ctx){await ensureDatabase(ctx.env);await ensureVision14Schema(ctx.env);const auth=await requireBoss(ctx);if(auth.error)return auth.error;const source=await ctx.env.DB.prepare('SELECT object_key,original_file_name FROM vision14_sources WHERE id=?').bind(ctx.params.id).first();if(!source)return json({error:'ไม่พบต้นฉบับ'},404);const object=await ctx.env.FILES.get(source.object_key);if(!object)return json({error:'ไม่พบไฟล์ PDF ในคลัง'},404);return new Response(object.body,{headers:{'content-type':'application/pdf','content-disposition':`inline; filename="vision14-source.pdf"`,'cache-control':'private, no-store','x-content-type-options':'nosniff'}})}
