import {json,requireBoss} from '../../../_lib.js';import {ensureDatabase} from '../../../_schema.js';import {canSellWithRights,ensureVision14Schema} from '../../../_vision14.js';const headers={'cache-control':'private, no-store'};
async function auth(ctx){await ensureDatabase(ctx.env);await ensureVision14Schema(ctx.env);return requireBoss(ctx)}
export async function onRequestGet(ctx){const a=await auth(ctx);if(a.error)return a.error;const row=await ctx.env.DB.prepare(`SELECT d.*,s.title FROM vision14_teaching_documents d JOIN vision14_sources s ON s.id=d.source_id WHERE d.source_id=?`).bind(ctx.params.id).first();if(!row)return json({error:'ยังไม่มี PDF สอนของจาวิส'},404,headers);const object=await ctx.env.FILES.get(row.object_key);if(!object)return json({error:'ไม่พบไฟล์ PDF ในพื้นที่จัดเก็บ'},404,headers);const responseHeaders=new Headers(headers);responseHeaders.set('content-type','application/pdf');responseHeaders.set('content-disposition',`attachment; filename="vision14-teaching-${row.id}.pdf"`);responseHeaders.set('content-length',String(row.file_size));return new Response(object.body,{headers:responseHeaders})}
export async function onRequestPost(ctx){const a=await auth(ctx);if(a.error)return a.error;if(!ctx.env.FILES)return json({error:'ยังไม่ได้เชื่อม R2 FILES'},503,headers);const source=await ctx.env.DB.prepare(`SELECT s.id,s.rights_status,s.sale_eligible,m.id summary_id,m.covered_pages,m.total_pages FROM vision14_sources s JOIN vision14_book_summaries m ON m.source_id=s.id WHERE s.id=?`).bind(ctx.params.id).first();if(!source)return json({error:'ต้องสร้างสรุปรายเล่มก่อน'},409,headers);const coverage=source.total_pages?Math.round(source.covered_pages/source.total_pages*100):0;if(coverage<80)return json({error:`Coverage ${coverage}% ต่ำกว่าเกณฑ์ 80% กรุณาแก้หน้าที่อ่านไม่สำเร็จก่อน`},409,headers);const form=await ctx.request.formData(),file=form.get('file'),pages=Number(form.get('page_count'));if(!(file instanceof File)||file.type!=='application/pdf'||!file.size||file.size>25*1024*1024)return json({error:'PDF สอนต้องไม่เกิน 25 MB'},400,headers);if(!Number.isInteger(pages)||pages<1||pages>500)return json({error:'จำนวนหน้า PDF ไม่ถูกต้อง'},400,headers);const old=await ctx.env.DB.prepare('SELECT object_key FROM vision14_teaching_documents WHERE source_id=?').bind(source.id).first(),key=`vision14/teaching/${source.id}-${crypto.randomUUID()}.pdf`;await ctx.env.FILES.put(key,await file.arrayBuffer(),{httpMetadata:{contentType:'application/pdf'},customMetadata:{sourceId:source.id,coverage:String(coverage)}});try{await ctx.env.DB.prepare(`INSERT INTO vision14_teaching_documents(source_id,summary_id,object_key,file_size,page_count,coverage_percent,rights_status,downstream_sale_allowed,created_by) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(source_id) DO UPDATE SET summary_id=excluded.summary_id,object_key=excluded.object_key,file_size=excluded.file_size,page_count=excluded.page_count,coverage_percent=excluded.coverage_percent,rights_status=excluded.rights_status,downstream_sale_allowed=excluded.downstream_sale_allowed,created_by=excluded.created_by,updated_at=CURRENT_TIMESTAMP`).bind(source.id,source.summary_id,key,file.size,pages,coverage,source.rights_status,canSellWithRights(source.rights_status)?1:0,a.user.id).run();if(old?.object_key)await ctx.env.FILES.delete(old.object_key);await ctx.env.DB.prepare("UPDATE vision14_sources SET processing_status='teaching_pdf_ready',updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(source.id).run()}catch(error){await ctx.env.FILES.delete(key);throw error}return json({ok:true,page_count:pages,file_size:file.size,coverage_percent:coverage,rights_status:source.rights_status,downstream_sale_allowed:canSellWithRights(source.rights_status)},201,headers)}
