import {decryptMetaParticipant} from './_meta_crypto.js';
import {withinMetaReplyWindow} from './_meta_messenger.js';
import {ensureVision7Schema} from './_vision7_schema.js';
const clean=(v,n=2000)=>String(v||'').normalize('NFKC').trim().slice(0,n),retryMinutes=[1,5,30,120,720];
const config=env=>{const token=String(env?.META_PAGE_ACCESS_TOKEN||''),pageId=String(env?.META_PAGE_ID||''),version=String(env?.META_GRAPH_API_VERSION||'');if(token.length<20)throw new Error('META_PAGE_ACCESS_TOKEN_NOT_CONFIGURED');if(!/^\d{5,30}$/.test(pageId))throw new Error('META_PAGE_ID_NOT_CONFIGURED');if(!/^v\d{1,2}\.\d{1,2}$/.test(version))throw new Error('META_GRAPH_API_VERSION_NOT_CONFIGURED');return {token,pageId,version}};
export async function queueMetaReply(env,{conversationId,content,createdBy,idempotencyKey}={}){await ensureVision7Schema(env);const text=clean(content);if(!text)return {error:'กรุณากรอกข้อความ',status:400};const conversation=await env.DB.prepare(`SELECT id,status,last_customer_message_at FROM elon_page_conversations WHERE id=?`).bind(conversationId).first();if(!conversation)return {error:'ไม่พบบทสนทนา',status:404};if(!withinMetaReplyWindow(conversation.last_customer_message_at))return {error:'พ้นกรอบตอบกลับ 24 ชั่วโมงของ Meta แล้ว',status:409,code:'META_24H_WINDOW_EXPIRED'};const id=crypto.randomUUID(),key=clean(idempotencyKey,160)||conversationId+':'+id,actor=createdBy||null;const result=await env.DB.prepare(`INSERT OR IGNORE INTO elon_page_outbox(id,idempotency_key,conversation_id,content,created_by) VALUES(?,?,?,?,?)`).bind(id,key,conversationId,text,actor).run();if(!result.meta?.changes){const existing=await env.DB.prepare('SELECT id,status FROM elon_page_outbox WHERE idempotency_key=?').bind(key).first();return {ok:true,duplicate:true,...existing}}await env.DB.prepare(`UPDATE elon_page_conversations SET status=CASE WHEN ? IS NULL THEN status ELSE 'human_active' END,assigned_user_id=CASE WHEN ? IS NULL THEN assigned_user_id ELSE COALESCE(assigned_user_id,?) END,updated_at=CURRENT_TIMESTAMP WHERE id=? AND status<>'closed'`).bind(actor,actor,actor,conversationId).run();return {ok:true,id,status:'queued'}}
export async function processMetaOutbox(env,{limit=10}={}){await ensureVision7Schema(env);const cfg=config(env),rows=(await env.DB.prepare(`SELECT o.*,c.participant_ciphertext,c.last_customer_message_at FROM elon_page_outbox o JOIN elon_page_conversations c ON c.id=o.conversation_id WHERE o.status IN ('queued','failed') AND o.next_attempt_at<=CURRENT_TIMESTAMP ORDER BY o.created_at LIMIT ?`).bind(Math.min(50,Math.max(1,Number(limit)||10))).all()).results||[],results=[];for(const row of rows){const claimed=await env.DB.prepare(`UPDATE elon_page_outbox SET status='sending',attempts=attempts+1 WHERE id=? AND status IN ('queued','failed')`).bind(row.id).run();if(!claimed.meta?.changes)continue;if(!withinMetaReplyWindow(row.last_customer_message_at)){await env.DB.prepare(`UPDATE elon_page_outbox SET status='dead',last_error='META_24H_WINDOW_EXPIRED' WHERE id=?`).bind(row.id).run();results.push({id:row.id,status:'dead',code:'META_24H_WINDOW_EXPIRED'});continue}try{const recipient=await decryptMetaParticipant(env,row.participant_ciphertext),response=await fetch(`https://graph.facebook.com/${cfg.version}/${cfg.pageId}/messages`,{method:'POST',headers:{authorization:`Bearer ${cfg.token}`,'content-type':'application/json'},body:JSON.stringify({recipient:{id:recipient},messaging_type:'RESPONSE',message:{text:row.content}})}),data=await response.json().catch(()=>({}));if(!response.ok||data?.error)throw new Error(`META_SEND_${data?.error?.code||response.status}`);await env.DB.batch([env.DB.prepare(`UPDATE elon_page_outbox SET status='sent',sent_at=CURRENT_TIMESTAMP,last_error='' WHERE id=?`).bind(row.id),env.DB.prepare(`INSERT INTO elon_page_messages(conversation_id,platform_message_id,role,content,mode,metadata) VALUES(?,?,?,?,'page_sales',?)`).bind(row.conversation_id,String(data.message_id||row.id),row.created_by?'human':'assistant',row.content,JSON.stringify({outbox_id:row.id,source:row.created_by?'operator':'page_sales_ai'})),env.DB.prepare(`UPDATE elon_page_conversations SET last_outbound_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(row.conversation_id)]);results.push({id:row.id,status:'sent'})}catch(error){const attempts=Number(row.attempts)+1,dead=attempts>=retryMinutes.length,minutes=retryMinutes[Math.min(attempts-1,retryMinutes.length-1)],modifier=`+${minutes} minutes`,code=clean(error?.message,100);await env.DB.prepare(`UPDATE elon_page_outbox SET status=?,next_attempt_at=datetime('now',?),last_error=? WHERE id=?`).bind(dead?'dead':'failed',modifier,code,row.id).run();results.push({id:row.id,status:dead?'dead':'failed',code})}}return {processed:results.length,results}}
