import {json} from '../../../../_lib.js';
import {ensureDatabase} from '../../../../_schema.js';
import {requirePartnerScope} from '../../../../_partner_api.js';
import {partnerDelivery} from '../../../../_partner_delivery.js';
const previews=value=>{try{const parsed=JSON.parse(value||'[]');return Array.isArray(parsed)?parsed.filter(url=>/^https?:\/\/|^\//.test(String(url))).slice(0,10):[]}catch{return []}};
const integer=(value,fallback,min,max)=>{if(value===null||value==='')return fallback;if(!/^\d+$/.test(value))return fallback;const parsed=Number(value);return Number.isSafeInteger(parsed)?Math.min(max,Math.max(min,parsed)):fallback};
export async function onRequestGet(ctx){await ensureDatabase(ctx.env);const auth=await requirePartnerScope(ctx,'products:read');if(auth.error)return auth.error;const url=new URL(ctx.request.url),limit=integer(url.searchParams.get('limit'),50,1,100),cursor=integer(url.searchParams.get('cursor'),0,0,Number.MAX_SAFE_INTEGER),category=String(url.searchParams.get('category')||'').trim().slice(0,80),where=category?'AND p.category=?':'',bindings=category?[category,cursor,limit+1]:[cursor,limit+1],rows=(await ctx.env.DB.prepare(`WITH selected AS (SELECT p.id,p.slug,p.title,p.short_description,p.description,p.price,p.cover_url,p.preview_urls,p.category,p.file_type,p.pages,p.product_kind,p.updated_at FROM products p WHERE p.status='published' AND p.deleted_at IS NULL AND p.id>? AND COALESCE(p.product_kind,'product') IN ('product','vision7-key') AND p.category<>'resale-rights' ${where} ORDER BY p.id LIMIT ?),own_files AS (SELECT pf.product_id,COUNT(*) file_count,SUM(pf.file_size) total_size FROM product_files pf JOIN selected p ON p.id=pf.product_id GROUP BY pf.product_id),bundle_files AS (SELECT b.bundle_product_id product_id,COUNT(pf.id) file_count,SUM(pf.file_size) total_size FROM product_bundle_items b JOIN selected p ON p.id=b.bundle_product_id LEFT JOIN product_files pf ON pf.product_id=b.source_product_id GROUP BY b.bundle_product_id),bundle_items AS (SELECT b.bundle_product_id product_id,COUNT(*) item_count FROM product_bundle_items b JOIN selected p ON p.id=b.bundle_product_id GROUP BY b.bundle_product_id) SELECT p.*,COALESCE(own_files.file_count,0)+COALESCE(bundle_files.file_count,0) delivery_file_count,COALESCE(own_files.total_size,0)+COALESCE(bundle_files.total_size,0) delivery_total_size,COALESCE(bundle_items.item_count,0) delivery_bundle_item_count FROM selected p LEFT JOIN own_files ON own_files.product_id=p.id LEFT JOIN bundle_files ON bundle_files.product_id=p.id LEFT JOIN bundle_items ON bundle_items.product_id=p.id ORDER BY p.id`).bind(...bindings).all()).results||[],hasMore=rows.length>limit,items=rows.slice(0,limit).map(item=>{const delivery=partnerDelivery(item);delete item.delivery_file_count;delete item.delivery_total_size;delete item.delivery_bundle_item_count;return{...item,price_currency:'THB',preview_urls:previews(item.preview_urls),delivery}});return json({website:{id:auth.website.id,name:auth.website.name},items,pagination:{limit,has_more:hasMore,next_cursor:hasMore?items.at(-1)?.id:null},request_id:auth.requestId},200,{'cache-control':'private, max-age=60','x-request-id':auth.requestId})}
